private void releaseAllFramesFromMediaCodec(CountDownLatch latch){
  try {
    removeAllSurfaceTextureFrames();
    if (pendingFrames.isEmpty() || (firstTryToRemoveAllFramesTimeMs != C.TIME_UNSET && SystemClock.DEFAULT.currentTimeMillis() - firstTryToRemoveAllFramesTimeMs >= SURFACE_TEXTURE_TIMEOUT_MS)) {
      firstTryToRemoveAllFramesTimeMs=C.TIME_UNSET;
      latch.countDown();
      return;
    }
    if (firstTryToRemoveAllFramesTimeMs == C.TIME_UNSET) {
      firstTryToRemoveAllFramesTimeMs=SystemClock.DEFAULT.currentTimeMillis();
    }
    Future<?> unusedFuture=scheduledExecutorService.schedule(() -> videoFrameProcessingTaskExecutor.submit(() -> releaseAllFramesFromMediaCodec(latch)),SURFACE_TEXTURE_WAIT_DELAY_MS,MILLISECONDS);
  } catch (NoSuchElementException e) {
    latch.countDown();
  } catch (RejectedExecutionException e) {
    latch.countDown();
  }
}
